TASK:{"title":"AERO9500 Final Report (Part 2)","overview":"Design a simple preliminary space mission benefiting Australia and identify main elements of its space segment, demonstrating understanding of space segment systems (launch, orbits etc.) using mission design software plus hand calculations."}
RUBRIC:[{"id":"C1","name":"Introduction: mission concept and rationale","weight":10,"max":null,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Addresses all requirements to a high standard. Detailed descriptions and discussions included. References to literature as appropriate."},{"label":"Adequate","min":4,"max":6,"desc":"Addresses some requirements. Descriptions may lack specific details and/or incomplete referencing."},{"label":"Deficient","min":0,"max":3,"desc":"Many or all requirements not addressed. Poor descriptions or lack of appropriate referencing."}]},{"id":"C2","name":"Main body: mission design","weight":60,"max":null,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Demonstrates high-level understanding of design procedure. Design clearly addresses mission and course concepts. All major requirements addressed and well-supported with quality evidence (screenshots, software files, hand calculations, literature). Content comprehensive, accurate, and persuasive."},{"label":"Adequate","min":4,"max":6,"desc":"Demonstrates adequate understanding of design procedure. Design maybe inconsistent regarding purpose and clarity or features errors. Major requirements addressed but may lack detail or evidence. Content may not be comprehensive or persuasive."},{"label":"Deficient","min":0,"max":3,"desc":"Demonstrates minimal understanding of design procedure. Major requirements not addressed and/or lack evidence. Content incomplete or not persuasive."}]},{"id":"C3","name":"Conclusion","weight":10,"max":null,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Detailed and appropriate conclusions reached from the evidence provided in the report."},{"label":"Adequate","min":4,"max":6,"desc":"Some conclusions reached but generic or lacking specific detail."},{"label":"Deficient","min":0,"max":3,"desc":"No actual or useful conclusions reached."}]},{"id":"C4","name":"Report presentation","weight":20,"max":null,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Follows clear and logical engineering report structure. Easy to read, well-written, good spelling/grammar, appropriate style. Consistent formatting. Executive summary/abstract provides concise overview. Graphical/tabular data appropriate, clear, consistent. In-text references match reference list and properly cited."},{"label":"Adequate","min":4,"max":6,"desc":"Not professional level but uses headings/subheadings. Report may be difficult to read: writing just ok, broad idea clear, spelling/grammar flaws, somewhat inappropriate style. Figures/tables labelled but formatting unclear/inconsistent causing loss of context. References mostly match list and mostly correctly cited."},{"label":"Deficient","min":0,"max":3,"desc":"Poorly structured, not coherent, shows lack of understanding of section purpose. Requires much effort to read: poor writing, many spelling/grammar mistakes, possibly inappropriate informal style. Presentation impedes reading. Inconsistent formatting, unlabelled figures/tables. References not cited or inconsistently cited."}]}]
MARKING:{"requirements":[{"id":"R1","met":"yes","page":4},{"id":"R2","met":"yes","page":5},{"id":"R3","met":"yes","page":5},{"id":"R4","met":"yes","page":8},{"id":"R5","met":"yes","page":11},{"id":"R6","met":"partial","page":12},{"id":"R7","met":"yes","page":13},{"id":"R8","met":"yes","page":15},{"id":"R9","met":"yes","page":10},{"id":"R10","met":"yes","page":6}],"technical_issues":[{"page":12,"issue":"COE table lists RAAN 27.33 deg as launch facility location; RAAN is Earth-inertial and not equal to launch longitude, misunderstanding."},{"page":11,"issue":"Missing communication frequency / link budget; requirement to define frequency not addressed."},{"page":17,"issue":"Uses Wikipedia https://en.wikipedia.org/wiki/2021_in_spaceflight [6] as reference which brief states not acceptable."},{"page":15,"issue":"EOL drag sail description truncated: 'utilising a large surface area to ‘ and is suitable' - incomplete."}],"overall":"Solid coral-reef monitoring mission with SSO design, STK analysis, and justified launch/ground choices. Minor technical gaps: RAAN definition, missing frequency, Wikipedia citation, and limited maneuver detail.","criteria":[{"id":"C1","level":"Accomplished","mark":8.0,"scale":10.0,"points":8.0,"max":10.0,"reasoning":"Defines coral reef monitoring to benefit Australia, rationale with bleaching stats and fluid lensing, single satellite justification, users CSIRO/BOM/University/Gov. Referenced literature.","evidence":[{"page":4,"quote":"Coral reefs, specifically the Great Barrier Reef, would immensely benefit from dedicated"},{"page":5,"quote":"Thus, only one satellite is required. This also just allows for simplicity"},{"page":5,"quote":"would likely be used by governmental and science agencies (e.g. CSIRO, BOM)"}]},{"id":"C2","level":"Accomplished","mark":7.0,"scale":10.0,"points":42.0,"max":60.0,"reasoning":"Covers launch, sun-synchronous LEO 600km with COEs, STK screenshots, ground access report, EOL drag sail. Some logic gaps and missing frequency.","evidence":[{"page":8,"quote":"The proposed satellite will thus use the Vega E rocket as a launch vehicle"},{"page":11,"quote":"Specifically, an altitude of 600km requires a mean inclination of 97.7924°"},{"page":13,"quote":"ground facility within Australia will suffice. As explained, a more polar latitude"}]},{"id":"C3","level":"Accomplished","mark":7.0,"scale":10.0,"points":7.0,"max":10.0,"reasoning":"Summarizes launch vehicle, orbit type, ground station, mission purpose and EOL, linked to evidence.","evidence":[{"page":16,"quote":"After analysis of each mission segment, a fully described satellite configuration has been constructed."}]},{"id":"C4","level":"Adequate","mark":6.0,"scale":10.0,"points":12.0,"max":20.0,"reasoning":"Clear headings, executive summary, figures labelled. Bibliography poorly formatted, Wikipedia used as source contrary to requirements, some incomplete sentences.","evidence":[{"page":2,"quote":"This report outlines the intended designs and procedures involved in the construction"},{"page":3,"quote":"Executive Summary ...........................................................................................2"}]}]}
